"""Render the principles as a Markdown operating guide."""

from __future__ import annotations

from typing import Iterable

from .principles import PRINCIPLES, TAG_TITLES, TAGS, Principle


def render(principles: Iterable[Principle] | None = None) -> str:
    items = list(PRINCIPLES if principles is None else principles)
    out = [
        "# Agent operating guide", "",
        "Generic principles for how an AI agent should work. "
        "Generated by `playbook render`; do not edit by hand.", "",
        "## Index", "",
    ]
    for p in items:
        out.append(f"- `{p.id}` - {p.title}")
    out.append("")
    for tag in TAGS:
        group = [p for p in items if p.applies_to and p.applies_to[0] == tag]
        if not group:
            continue
        out += [f"## {TAG_TITLES[tag]}", ""]
        for p in group:
            out += [
                f"### {p.title} (`{p.id}`)", "",
                f"**Rule.** {p.rule}", "",
                f"**Why.** {p.rationale}", "",
                "Tags: " + ", ".join(p.applies_to), "",
            ]
    return "\n".join(out).rstrip() + "\n"
